// ═══════════════════════════════════════════════════════════════════════════
// 任务名 / 物件名的中文接管（**主键不动，只改显示**）
// ═══════════════════════════════════════════════════════════════════════════
//
// 【为什么不能靠 XML 汉化】
//   反编译 `XRL.World.Quest`（工具 `_tools/decomp`）：
//
//       public string Name;                                   // ← 主键
//       public string DisplayName => "{{W|" + Name + "}}";    // ← 显示路径
//
//   而 `Name` 被大量逻辑当作**键**使用，实证（基础数据里搜到）：
//       Base\Conversations.xml:            IfFinishedQuest="What's Eating the Watervine?"
//       Base\ObjectBlueprints\Creatures.xml: <part Name="QuestStepFinisher"
//                                                   Quest="What's Eating the Watervine?" Step="Find the Vermin" />
//       Base\ObjectBlueprints\Widgets.xml:  同 Quest= 引用
//
//   ⇒ **改 `Name` 会直接破坏任务完成判定** —— 这正是「210.20 汉化补丁卡任务进度」
//     那个 bug 的成因（历史教训，本项目 `Quests.xml` 的注释也写着「绝不动 Name 属性」）。
//
//   ⇒ 正确做法：`Name` 保持英文不动，**只接管显示出口**。
//
// 【本补丁做什么】
//   1. 挂 `Quest.DisplayName` 的 getter → 返回中文任务名（含 `{{W|…}}` 标记）
//   2. 挂 `GameObjectBlueprint.DisplayName()` → 返回中文物件名
//   3. `Name` / `ID` / 一切都**原样不动**
//
//   ⇒ 任务判定、存档、继承链全部不受影响。
// ═══════════════════════════════════════════════════════════════════════════

