        public static void TryApply()
        {
            if (_applied) return;
            _applied = true;

            int n = 0;
            n += PatchGetter("XRL.World.Quest", "DisplayName", "QuestPostfix", "quest");
            n += PatchDisplayNameMethod("XRL.World.GameObjectBlueprint", "obj");
            // ★ 物件名的真正出口：GameObject.DisplayName（getter）。
            //   蓝图级 DisplayName() 只给单数原形，而游戏显示的是经过复数/语法
            //   变换的结果（flowers、low walls…），单靠蓝图级会漏掉复数名。
            n += PatchGetter("XRL.World.GameObject", "DisplayName", "ObjPostfix", "objinst");

            // ★★ 物件名的**总闸**：GameObject.GetDisplayName(...) 全部汇到
            //    XRL.Language.Translator.GameObjectDisplayName(...)（static）。
            //    而 `=object.the.name:itsPossessor=` 之类的替换器走
            //    GameObject.ShortDisplayName → Render.DisplayName（纯英文），
            //    **不经过** GameObject.DisplayName 属性 ⇒ 必须挂这一路。
            n += PatchTranslatorDisplayName();

            UnityEngine.Debug.Log(Tag + "已挂 " + n + " 个名称显示出口"
                + "（任务 " + QuestNames.Count + " 条 · 物件 " + ObjectNames.Count + " 条映射）");
        }

        private static Type FindType(string full)
        {
            foreach (Assembly asm in AppDomain.CurrentDomain.GetAssemblies())
            {
                try
                {
                    Type t = asm.GetType(full, false);
                    if (t != null) return t;
                }
                catch { }
            }
            return null;
        }


        /// <summary>挂 `XRL.Language.Translator.GameObjectDisplayName`（所有 GetDisplayName 的汇合点）。</summary>
        private static int PatchTranslatorDisplayName()
        {
            Type t = FindType("XRL.Language.Translator");
            if (t == null) { UnityEngine.Debug.LogError(Tag + "找不到 XRL.Language.Translator"); return 0; }
            int n = 0;
            foreach (MethodInfo mi in t.GetMethods(BindingFlags.Public | BindingFlags.NonPublic
                                                   | BindingFlags.Static))
            {
                if (mi.Name != "GameObjectDisplayName") continue;
                if (mi.ReturnType != typeof(string)) continue;
                ParameterInfo[] ps = mi.GetParameters();
                // 目标签名：第一个参数是 XRL.World.GameObject，第二个是 out bool
                if (ps.Length < 2 || ps[0].ParameterType.Name != "GameObject") continue;
                if (ps[1].ParameterType.Name != "Boolean&") continue;
                n += Patch(mi, "ObjPostfix", "translator");
            }
            if (n == 0) UnityEngine.Debug.LogError(Tag + "Translator.GameObjectDisplayName 未挂上");
            return n;
        }

        /// <summary>挂属性的 getter。</summary>
        private static int PatchGetter(string typeName, string propName,
                                       string postfixName, string kind)
        {
            Type t = FindType(typeName);
            if (t == null) { UnityEngine.Debug.LogError(Tag + "找不到 " + typeName); return 0; }
            PropertyInfo pi = t.GetProperty(propName,
                BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
            if (pi == null) { UnityEngine.Debug.LogError(Tag + "找不到 " + typeName + "." + propName); return 0; }
            MethodInfo getter = pi.GetGetMethod(true);
            if (getter == null) return 0;
            return Patch(getter, postfixName, kind);
        }

        /// <summary>挂无参方法（如 GameObjectBlueprint.DisplayName()）。</summary>
        private static int PatchDisplayNameMethod(string typeName, string kind)
        {
            Type t = FindType(typeName);
            if (t == null) { UnityEngine.Debug.LogError(Tag + "找不到 " + typeName); return 0; }
            int n = 0;
            foreach (MethodInfo mi in t.GetMethods(BindingFlags.Public | BindingFlags.NonPublic
                                                   | BindingFlags.Instance))
            {
                if (mi.Name != "DisplayName") continue;
                if (mi.GetParameters().Length != 0) continue;
                if (mi.ReturnType != typeof(string)) continue;
                n += Patch(mi, "ObjPostfix", kind);
            }
            return n;
        }

        private static int Patch(MethodInfo target, string postfixName, string kind)
        {
            try
            {
                MethodInfo post = typeof(ZhsNameDisplayPatch).GetMethod(
                    postfixName, BindingFlags.NonPublic | BindingFlags.Static);
                if (post == null) return 0;
                Harmony h = new Harmony("Nattens.QudZhsCookbook.namedisplay."
                    + kind + "." + target.DeclaringType.Name + "." + target.Name);
                h.Patch(target, postfix: new HarmonyMethod(post));
                return 1;
            }
            catch (Exception e)
            {
                UnityEngine.Debug.LogError(Tag + "挂 " + target.Name + " 失败：" + e.Message);
                return 0;
            }
        }

        // ────────────────────────────────────────────────────────────────
        // 1) 任务名：`{{W|Name}}` → `{{W|中文名}}`
        // ────────────────────────────────────────────────────────────────
        private static void QuestPostfix(ref string __result)
        {
            try
            {
                if (string.IsNullOrEmpty(__result)) return;
                if (Markup.HasCjk(__result)) return;              // 幂等

                foreach (var kv in QuestNames)
                {
                    if (__result.IndexOf(kv.Key, StringComparison.Ordinal) < 0) continue;
                    string rep = __result.Replace(kv.Key, kv.Value);
                    _questHits++;
                    if (_questHits <= 25)
                        UnityEngine.Debug.Log(Tag + "任务名：" + __result + "  =>  " + rep);
                    __result = rep;
                    return;
                }
            }
            catch { }
        }

        // ────────────────────────────────────────────────────────────────
        // 2) 物件名：`Render.DisplayName` 的返回值
        // ────────────────────────────────────────────────────────────────
        private static void ObjPostfix(ref string __result)
        {
            try
            {
                if (string.IsNullOrEmpty(__result)) return;
                if (Markup.HasCjk(__result)) return;

                string t = __result.Trim();

                // ★ 第二人称主语兜底：`=subject.the.name=` 对玩家返回 "you"，
                //   中文模板（如 `Inventory take` → `=subject.the.name=拿到了…`）需要「你」。
                //   `ZhsPronounPatch` 有同样映射但因故停用，这里直接补。
                if (t == "you" || t == "You")
                {
                    __result = "你";       // 你
                    return;
                }

                string zh;
                if (ObjectNames.TryGetValue(t, out zh))
                {
                    _objHits++;
                    if (_objHits <= 25)
                        UnityEngine.Debug.Log(Tag + "物件名：" + __result + "  =>  " + zh);
                    __result = zh;
                }
            }
            catch { }
        }

        public static void Report()
        {
            UnityEngine.Debug.Log(Tag + "统计：任务名替换 " + _questHits
                + " 次，物件名替换 " + _objHits + " 次");
        }
    }
}
